WFJ.Data.add("spell", {
  [408024] = { "Quando attivato, ti conferisce il $N1% della tua salute massima e aumenta del $N2% tutte le cure non fisiche che effettui per $D1. Al termine dell'effetto, la salute viene persa. Utilizzabile in tutte le forme tranne la ⟦Moonkin Form=Forma di Lunagufo⟧.\n\nInoltre, rigeneri $N4 rabbia ogni volta che schivi in ⟦Bear Form=Forma d'Orso⟧ o Dire Bear Form, $N5 energia in ⟦Cat Form=Forma Felina⟧, o il $N6% del tuo mana massimo in qualsiasi altra forma.", "Salute aumentata del $N1% del massimo.", 0xf0735027, 0x414996c4, "uu" },
  [408120] = { "Cura il bersaglio e il suo gruppo di $N1 in $D1. I membri del gruppo devono trovarsi entro $N3 m dal bersaglio. La cura è rapida all'inizio e rallenta man mano che Crescita Rigogliosa si avvicina al termine della sua durata.", "Cura $N1 danni ogni $N2 s.", 0x1cb536f6, 0xcf751a77, "uu" },
  [408124] = { "Cura il bersaglio di $N1 in $D1. Quando Bocciolo di Vita giunge al termine della sua durata o viene dissolto, il bersaglio viene curato istantaneamente di $N3 e il Druido recupera metà del costo dell'incantesimo. Questo effetto può accumularsi fino a $N4 volte sullo stesso bersaglio.", "Cura $N1 ogni secondo e $N2 quando l'effetto termina o viene dissolto.", 0x8ddbb673, 0x57b19551, "uu" },
  [408245] = { "Cura il bersaglio in $D1. Quando Bocciolo di Vita giunge al termine della sua durata o viene dissolto, il bersaglio viene curato istantaneamente. Questo effetto può accumularsi fino a $N2 volte sullo stesso bersaglio.", nil, 0x2a59bfb7, nil, "um" },
  [408246] = { "Ottieni mana quando Bocciolo di Vita termina.", nil, 0xa7aa89d1, nil, "um" },
  [408247] = { "Cura un bersaglio alleato di $N1. La cura è superiore del $N2% se sul bersaglio è attivo un tuo effetto di Rinvigorimento, Ricrescita, Bocciolo di Vita o Crescita Rigogliosa. Questo incantesimo beneficia di tutti gli effetti associati a ⟦Healing Touch=Tocco Curativo⟧ o Ricrescita e li attiva.", nil, 0x2a601efa, nil, "um" },
  [408248] = { "Ira Silvana riduce di $D1 il tempo di lancio dei tuoi prossimi $N1 Fuoco Stellare. Accumula fino a $N3 cariche. Dura $D2.", nil, 0x90e893e0, nil, "um" },
  [408255] = { nil, "I tuoi prossimi $N1 Fuoco Stellare hanno il tempo di lancio ridotto di $D1.", nil, 0x727e4f27, "mu" },
  [408258] = { "I colpi critici dei tuoi incantesimi di danno non periodici ti permettono di mantenere il $N1% della tua rigenerazione del mana durante il lancio per $D1.", nil, 0x0e52fe0b, nil, "um" },
  [408261] = { "Permette al $N1% della rigenerazione del mana di continuare durante il lancio di incantesimi.", "Mantieni il $N1% della normale rigenerazione del mana durante il lancio di incantesimi.", 0x86815c0c, 0x7a27f000, "uu" },
  [408307] = { "Aumenta le tue cure di un valore pari al $N1% dei tuoi danni magici da natura per $D1.", "Cure aumentate di $N1.", 0x582306b5, 0xfda8744a, "uu" },
  [408309] = { "Aumenta i tuoi danni magici di un valore pari al $N1% della differenza tra le tue cure e i tuoi danni magici. Dura $D1.", "Danni magici aumentati di $N1.", 0xd596949e, 0x62dc13bd, "uu" },
  [408339] = { "Il tuo incantesimo ⟦Fire Nova Totem=Totem dell'Esplosione di Fuoco⟧ è sostituito da ⟦Fire Nova=Esplosione di Fuoco⟧, che fa emettere danni al tuo totem del fuoco attuale nel punto in cui si trova.", nil, 0x2cf7852b, nil, "um" },
  [408341] = { "Infligge istantaneamente $N1 danni da fuoco ai nemici entro $N2 m dal tuo totem del fuoco attivo.", nil, 0x3039ca50, nil, "um" },
  [408342] = { "Infligge istantaneamente $N1 danni da fuoco ai nemici entro $N2 m dal tuo totem del fuoco attivo.", nil, 0x3fb794d0, nil, "um" },
  [408343] = { "Infligge istantaneamente $N1 danni da fuoco ai nemici entro $N2 m dal tuo totem del fuoco attivo.", nil, 0x5eb329d0, nil, "um" },
  [408344] = { "Infligge istantaneamente $N1 danni da fuoco ai nemici entro $N2 m dal tuo totem del fuoco attivo.", nil, 0x6e30f450, nil, "um" },
  [408345] = { "Infligge istantaneamente $N1 danni da fuoco ai nemici entro $N2 m dal tuo totem del fuoco attivo.", nil, 0x7daebed0, nil, "um" },
  [408438] = { "Conferisce a ⟦Lightning Bolt=Dardo Fulminante⟧ e ⟦Chain Lightning=Catena di Fulmini⟧ una probabilità del $N1% di lanciare sullo stesso bersaglio, senza costi aggiuntivi, un secondo incantesimo simile che infligge metà dei danni e non genera minaccia.", nil, 0x43e46bfc, nil, "um" },
  [408439] = { "Scaglia un fulmine contro il bersaglio, infliggendo $N1 danni da natura.", nil, 0x50eaf6a6, nil, "um" },
