  [408479] = { "Scaglia un fulmine contro il nemico, infliggendo $N1 danni da natura e propagandosi poi ad altri nemici vicini. Ogni salto riduce i danni del $N2%. Colpisce $N3 bersagli in totale.", nil, 0xbf3e3b89, nil, "um" },
  [408481] = { "Scaglia un fulmine contro il nemico, infliggendo $N1 danni da natura e propagandosi poi ad altri nemici vicini. Ogni salto riduce i danni del $N2%. Colpisce $N3 bersagli in totale.", nil, 0xbf3e3b89, nil, "um" },
  [408482] = { "Scaglia un fulmine contro il nemico, infliggendo $N1 danni da natura e propagandosi poi ad altri nemici vicini. Ogni salto riduce i danni del $N2%. Colpisce $N3 bersagli in totale.", nil, 0xbf3e3b89, nil, "um" },
  [408484] = { "Scaglia un fulmine contro il nemico, infliggendo $N1 danni da natura e propagandosi poi ad altri nemici vicini. Ogni salto riduce i danni del $N2%. Colpisce $N3 bersagli in totale.", nil, 0xbf3e3b89, nil, "um" },
  [408490] = { "Scagli lava fusa contro il bersaglio, infliggendo $N1 danni da fuoco. Se sul bersaglio è attiva la tua ⟦Flame Shock=Folgore del Fuoco⟧, ⟦Lava Burst=Getto di Lava⟧ infligge il $N2% di danni in più.", nil, 0xc9c1c783, nil, "um" },
  [408491] = { "Scagli lava fusa contro il bersaglio, infliggendo $N1 danni da fuoco. Se sul bersaglio è attiva la tua ⟦Flame Shock=Folgore del Fuoco⟧, ⟦Lava Burst=Getto di Lava⟧ infligge il $N2% di danni in più.", nil, 0x2838b0c8, nil, "um" },
  [408496] = { "Mentre combatti con due armi aumenta del $N1% la tua probabilità di colpire con incantesimi e attacchi in mischia, la tua abilità Assalto della Tempesta colpisce ora con entrambe le armi e i danni inflitti dalla tua arma secondaria aumentano del $N2%.", nil, 0x33e038b0, nil, "um" },
  [408498] = { "Quando infliggi danni con un attacco in mischia, hai una probabilità di ridurre del $N1% il tempo di lancio e il costo in mana del tuo prossimo ⟦Lightning Bolt=Dardo Fulminante⟧. Si accumula fino a $N2 volte. Dura $D1.", nil, 0x9a6cb9c7, nil, "um" },
  [408505] = { "Riduce il tempo di lancio e il costo in mana del tuo prossimo ⟦Lightning Bolt=Dardo Fulminante⟧.", "Riduce del $N1% il tempo di lancio e il costo in mana del tuo prossimo ⟦Lightning Bolt=Dardo Fulminante⟧.", 0xe17bbdf5, 0xf55df514, "uu" },
  [408507] = { "Carichi di lava la tua arma secondaria, infliggendo istantaneamente il $N1% dei danni dell'arma secondaria. I danni aumentano del $N2% se la tua arma secondaria è incantata con Flametongue.", nil, 0xfd5176b5, nil, "um" },
  [408510] = { "L'incantatore è circondato da $N1 globi d'acqua. Quando un incantesimo o un attacco in mischia o a distanza colpisce l'incantatore, o quando uno dei suoi incantesimi ottiene un risultato critico, l'incantatore recupera il $N2% del mana massimo, consumando un globo d'acqua. Si attiva un solo globo ogni pochi secondi. Dura $D1.\n\nSullo Sciamano può essere attivo un solo ⟦Elemental Shield=Scudo Elementale⟧ alla volta.", "Gli attacchi e gli incantesimi usati contro di te e i tuoi incantesimi critici ripristinano il $N1% del tuo mana massimo. $N2 cariche.", 0x69739dde, 0x752cd153, "uu" },
  [408511] = { "Ottieni mana quando vieni colpito mentre Scudo d'Acqua è attivo.", nil, 0x1d96f43d, nil, "um" },
  [408514] = { "Protegge il bersaglio con uno scudo di terra, riducendo del $N1% il tempo di lancio o di incanalamento perso quando subisce danni e facendo sì che gli attacchi curino il bersaglio schermato di $N2. Questo effetto può verificarsi solo una volta ogni pochi secondi. $N3 cariche. Dura $D1. ⟦Earth Shield=Scudo di Terra⟧ può essere applicato a un solo bersaglio alla volta.", "Riduce del $N1% il tempo di lancio o di incanalamento perso quando subisci danni, e gli attacchi curano il bersaglio schermato di $N2.", 0xbdee3645, 0x38d681af, "uu" },
  [408519] = { "Curato da ⟦Earth Shield=Scudo di Terra⟧.", nil, 0x1dc3ad48, nil, "um" },
  [408521] = { "Cura un bersaglio amico di $N1, più altri $N2 in $D1, e aumenta del $N4% l'efficacia dei tuoi lanci di ⟦Chain Heal=Catena di Guarigione⟧ diretti su quel bersaglio.", "Cura $N1 ogni $D1.\nAumenta del $N3% l'efficacia degli incantesimi ⟦Chain Heal=Catena di Guarigione⟧ dell'incantatore lanciati direttamente su questo bersaglio.", 0x68320edf, 0x0b6d739c, "uu" },
  [408524] = { "Ogni volta che blocchi, rigeneri mana pari al $N1% del tuo mana massimo e ottieni Armatura pari al $N2% del valore di armatura del tuo scudo, effetto che si accumula fino a $N3 volte. Inoltre ottieni sempre il $N4% di probabilità di blocco in più e il $N5% di valore di blocco in più.\n\nInoltre, ogni volta che usi un'abilità Folgore, ottieni $N6 danni magici per ogni punto di abilità in Difesa oltre $N7. Dura $D1.", nil, 0x6633c263, nil, "um" },
  [408525] = { "Aumenta l'Armatura di una quantità pari al $N1% del valore di armatura del tuo scudo per $D1, effetto che si accumula fino a $N3 volte.", "Armatura aumentata di $N1.", 0x8525df7d, 0x97da7cad, "uu" },
  [408531] = { "Mentre Arma della ⟦Rockbiter=Roccia Dura⟧ è attiva sulla tua arma nella mano primaria e hai uno scudo equipaggiato, generi il $N1% di minaccia in più, ottieni il $N2% di salute in più, subisci il $N3% di danni in meno, la tua probabilità di subire colpi critici dagli attacchi in mischia è ridotta del $N4%, e ⟦Earth Shock=Folgore della Terra⟧ provoca i bersagli inducendoli ad attaccarti e ha un tempo di recupero separato dagli altri incantesimi Folgore, ma la sua portata è ridotta alla distanza da mischia. Tuttavia, la portata dei tuoi incantesimi ⟦Lightning Bolt=Dardo Fulminante⟧, ⟦Chain Lightning=Catena di Fulmini⟧, ⟦Chain Heal=Catena di Guarigione⟧, ⟦Healing Wave=Ondata di Cura⟧ e ⟦Lava Burst=Getto di Lava⟧ è ridotta di $N5 m.", nil, 0x27fc7143, nil, "um" },
  [408680] = { "Mentre Arma della ⟦Rockbiter=Roccia Dura⟧ è attiva sulla tua arma nella mano primaria, generi il $N1% di minaccia in più, ottieni il $N2% di salute in più, subisci il $N3% di danni in meno, la tua probabilità di subire colpi critici dagli attacchi in mischia è ridotta del $N4%, e ⟦Earth Shock=Folgore della Terra⟧ provoca i bersagli inducendoli ad attaccarti e ha un tempo di recupero separato dagli altri incantesimi Folgore.", "Minaccia generata aumentata del $N1%. Salute aumentata del $N2%. ⟦Earth Shock=Folgore della Terra⟧ provoca i bersagli, inducendoli ad attaccarti. Danni subiti ridotti del $N3%. Probabilità di subire colpi critici in mischia ridotta del $N4%.", 0xefe15a43, 0xf9b0daa9, "uu" },
  [408681] = { "Colpisce istantaneamente il bersaglio con una forza d'urto, infliggendo $N1 danni da natura. Interrompe inoltre il lancio d'incantesimi e impedisce di lanciare incantesimi di quella scuola per $D1. Genera un'elevata quantità di minaccia e provoca il bersaglio.", "Provocato.", 0xcc9d1126, 0x36f56123, "uu" },
  [408683] = { "Colpisce istantaneamente il bersaglio con una forza d'urto, infliggendo $N1 danni da natura. Interrompe inoltre il lancio d'incantesimi e impedisce di lanciare incantesimi di quella scuola per $D1. Genera un'elevata quantità di minaccia e provoca il bersaglio.", "Provocato.", 0xcc9d1126, 0x36f56123, "uu" },
  [408685] = { "Colpisce istantaneamente il bersaglio con una forza d'urto, infliggendo $N1 danni da natura. Interrompe inoltre il lancio d'incantesimi e impedisce di lanciare incantesimi di quella scuola per $D1. Genera un'elevata quantità di minaccia e provoca il bersaglio.", "Provocato.", 0xcc9d1126, 0x36f56123, "uu" },
  [408687] = { "Colpisce istantaneamente il bersaglio con una forza d'urto, infliggendo $N1 danni da natura. Interrompe inoltre il lancio d'incantesimi e impedisce di lanciare incantesimi di quella scuola per $D1. Genera un'elevata quantità di minaccia e provoca il bersaglio.", "Provocato.", 0xcc9d1126, 0x36f56123, "uu" },
  [408688] = { "Colpisce istantaneamente il bersaglio con una forza d'urto, infliggendo $N1 danni da natura. Interrompe inoltre il lancio d'incantesimi e impedisce di lanciare incantesimi di quella scuola per $D1. Genera un'elevata quantità di minaccia e provoca il bersaglio.", "Provocato.", 0xcc9d1126, 0x36f56123, "uu" },
  [408689] = { "Colpisce istantaneamente il bersaglio con una forza d'urto, infliggendo $N1 danni da natura. Interrompe inoltre il lancio d'incantesimi e impedisce di lanciare incantesimi di quella scuola per $D1. Genera un'elevata quantità di minaccia e provoca il bersaglio.", "Provocato.", 0xcc9d1126, 0x36f56123, "uu" },
  [408690] = { "Colpisce istantaneamente il bersaglio con una forza d'urto, infliggendo $N1 danni da natura. Interrompe inoltre il lancio d'incantesimi e impedisce di lanciare incantesimi di quella scuola per $D1. Genera un'elevata quantità di minaccia e provoca il bersaglio.", "Provocato.", 0xcc9d1126, 0x36f56123, "uu" },
  [408693] = { "Costringe il bersaglio ad attaccarti, ma non ha effetto se il bersaglio ti sta già attaccando.", "Provocato.", 0x71de38fd, 0x36f56123, "uu" },
  [408696] = { "Infonde nel bersaglio lo spirito di un lupo alfa, aumentando del $N1% tutta la minaccia generata dal bersaglio per $D1. Limite: $N3 bersaglio. Se lanciato su un bersaglio diverso da te, lo Sciamano ottiene anche Loyal Beta, che aumenta del $N4% i danni fisici inflitti e riduce del $N5% tutta la minaccia generata per $D2. Un bersaglio non può avere contemporaneamente Spirit of the Alpha e Loyal Beta.", "Aumenta del $N1% la minaccia generata.", 0xfe54e326, 0x7d7c77fd, "uu" },
  [408699] = { "I tuoi colpi di Imboscata e Pugnalata alle Spalle sbilanciano il bersaglio, aumentando del $N1% l'intervallo tra i suoi attacchi in mischia e riducendone la velocità di movimento del $N2% per $D1.", "Tempo tra gli attacchi in mischia aumentato del $N1%.\nVelocità di movimento ridotta del $N2%.", 0x0089367c, 0x41ad20f4, "uu" },
  [408700] = { "I tuoi colpi di Imboscata e Pugnalata alle Spalle sbilanciano il bersaglio, aumentando del $N1% l'intervallo tra i suoi attacchi in mischia e riducendone la velocità di movimento del $N2% per $D1.", nil, 0x0089367c, nil, "um" },
  [408755] = { "Offri il tuo sangue per alimentare l'artefatto.", "Riduce del $N1% tutti gli attributi, del $N2% tutti i danni inflitti e del $N3% l'Armatura e le resistenze.", 0x091653f6, 0xbc5ee950, "uu" },
